        order = sorted(range(n), key=lambda x: degree[x], reverse=True)
        return greedy_color(order)

    # Smallest-Last ordering (Matula & Beck)
    def sl_coloring():
        # Peeling order: remove min degree vertex repeatedly
        deg = degree[:]  # copy
        removed = [False] * n
        order = []  # will be peeled order (first peeled first)
        for _ in range(n):
            # find unremoved vertex with min degree
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and deg[i] < min_deg:
