            for u in neighbors[v]:
                if not removed[u]:
                    deg[u] -= 1
        # color in reverse peeling order
        return greedy_color(order[::-1])

    # Recursive Largest First (RLF) - independent set extraction
    def rlf_coloring():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Step 1: choose vertex with max degree in G[uncolored]
            max_deg = -1
            v = -1
            for u in uncolored:
                d = 0
                for w in neighbors[u]:
                    if w in uncolored:
                        d += 1
                if d > max_deg:
                    max_deg = d
                    v = u
            if v == -1:
                break
            # Start independent set S with v
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                adjacent = False
                for w in S:
                    if w in neighbors[u]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            # While U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_score = -1
                best_u = -1
                for u in U:
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    if score > best_score:
                        best_score = score
                        best_u = u
                    elif score == best_score:
                        # Tie-break: min degree in G[U]
                        deg_u = 0
                        for w in neighbors[u]:
                            if w in U:
                                deg_u += 1
                        deg_best = 0
                        for w in neighbors[best_u]:
                            if w in U:
                                deg_best += 1
                        if deg_u < deg_best:
                            best_u = u
                if best_u == -1:
                    break  # should not happen if U not empty
                # Add best_u to S
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u that are in U to W
                for w in neighbors[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all vertices in S
            for u in S:
                color[u] = c
            # Remove S from uncolored
            uncolored -= S
            c += 1
        return color

    # Try all methods and keep the best (minimum colors)
    methods = [
        ("DSATUR", dsatur_coloring),
        ("Welsh-Powell", wp_coloring),
        ("Smallest-Last", sl_coloring),
        ("RLF", rlf_coloring)
    ]

    # Also try a few random orderings (shuffled degrees) for good measure
    for _ in range(5):
        order = list(range(n))
        random.shuffle(order)
        methods.append((f"Random-{_}", lambda o=order: greedy_color(o)))

    for name, func in methods:
        try:
            coloring = func()
            k = num_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring
        except Exception:
            # In case of any error, skip this method
            continue

    # Fallback: if no method succeeded (should not happen), use greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))

    return best_coloring

