    if n == 0:
        return []
    if n == 1:
        return [0]
    if all(len(neighbors[i]) == 0 for i in range(n)):
        return [0] * n
    if all(len(neighbors[i]) == n - 1 for i in range(n)):
        return list(range(n))

    # DSATUR with efficient saturation tracking
    color = [-1] * n
    sat = [0] * n  # saturation degree: number of distinct colors in neighbors
    neighbor_colors = [set() for _ in range(n)]  # set of colors used by neighbors
    uncolored_deg = [len(neighbors[i]) for i in range(n)]  # degree in uncolored subgraph
    uncolored = set(range(n))

    def select_vertex():
        if not uncolored:
            return None
        max_sat = -1
        candidates = []
        for v in uncolored:
            if sat[v] > max_sat:
                max_sat = sat[v]
                candidates = [v]
            elif sat[v] == max_sat:
                candidates.append(v)
        if len(candidates) == 1:
            return candidates[0]
