        max_deg = -1
        deg_candidates = []
        for v in candidates:
            d = uncolored_deg[v]
            if d > max_deg:
                max_deg = d
                deg_candidates = [v]
            elif d == max_deg:
                deg_candidates.append(v)
        if len(deg_candidates) == 1:
            return deg_candidates[0]
        # Final tie-break: random choice
        return random.choice(deg_candidates)

    # Main DSATUR loop
    while uncolored:
        v = select_vertex()
        used = neighbor_colors[v]
        c = 0
        while c in used:
            c += 1
        color[v] = c
        uncolored.remove(v)
        # Update uncolored degree of neighbors
        for u in neighbors[v]:
            if u in uncolored:
                uncolored_deg[u] -= 1
        # Update saturation of uncolored neighbors
        for u in neighbors[v]:
            if u in uncolored:
                if c not in neighbor_colors[u]:
                    neighbor_colors[u].add(c)
                    sat[u] += 1

    # Kempe chain refinement to reduce number of colors
    max_color = max(color) if n > 0 else -1
    # Process colors from highest to lowest
    for target_color in range(max_color, 0, -1):
        # Get vertices with current target color
        verts_target = [i for i in range(n) if color[i] == target_color]
        if not verts_target:
            continue
        changed = True
        while changed and verts_target:
            changed = False
            v = verts_target.pop()
            # Try direct recolor to a lower color
            for c in range(target_color):
                conflict = False
                for u in neighbors[v]:
                    if color[u] == c:
                        conflict = True
                        break
                if not conflict:
                    color[v] = c
                    changed = True
                    break
            if changed:
                continue
            # Try Kempe chain swap for each lower color
            for c in range(target_color):
                # BFS to find the Kempe chain component of v for colors (c, target_color)
                visited = set()
                queue = [v]
                visited.add(v)
                head = 0
                while head < len(queue):
                    node = queue[head]
                    head += 1
                    for nb in neighbors[node]:
                        if color[nb] == c or color[nb] == target_color:
                            if nb not in visited:
                                visited.add(nb)
                                queue.append(nb)
                # Check if swapping is safe: after swap, v becomes c, so no neighbor should be c after swap
                # After swap: neighbors that were c become target_color, neighbors that were target_color become c
                # So v (now c) conflicts iff there exists a neighbor u that was target_color (becomes c)
                conflict = False
                for u in neighbors[v]:
                    if color[u] == target_color:  # after swap, this neighbor becomes c -> conflict
                        conflict = True
                        break
                if not conflict:
                    # Perform swap in the component
                    for node in visited:
                        if color[node] == c:
                            color[node] = target_color
                        elif color[node] == target_color:
                            color[node] = c
                    changed = True
                    break  # break from color loop after successful Kempe swap
            # If we made a change, we need to rebuild verts_target for this target_color
            if changed:
                verts_target = [i for i in range(n) if color[i] == target_color]

    return color

