def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix
    is_matrix = True
    if len(adj[0]) != n:
        is_matrix = False
    else:
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor sets
    if is_matrix:
        neighbors = [set(j for j in range(n) if adj[i][j] == 1) for i in range(n)]
    else:
        neighbors = [set(lst) for lst in adj]

    # Ensure symmetry and no self-loops
    for i in range(n):
        if i in neighbors[i]:
            neighbors[i].remove(i)
        for j in neighbors[i]:
            if i not in neighbors[j]:
                neighbors[j].add(i)

    # Trivial cases
    if n == 1:
        return [0]
    total_edges = sum(len(neighbors[i]) for i in range(n)) // 2
    if total_edges == 0:
        return [0] * n

    # Helper: greedy coloring given an order
    def greedy_color(order):
        colors = [-1] * n
        max_color = 0
        for v in order:
            used = [False] * (max_color + 2)
            for u in neighbors[v]:
                if colors[u] != -1:
                    used[colors[u]] = True
            c = 0
            while c < len(used) and used[c]:
                c += 1
            colors[v] = c
            if c > max_color:
                max_color = c
        return colors, max_color + 1

    # 1. Smallest-Last (SL) Ordering
    remaining_set = set(range(n))
    temp_degree = [len(neighbors[i]) for i in range(n)]
    sl_order = []
    while remaining_set:
        v = min(remaining_set, key=lambda x: temp_degree[x])
        sl_order.append(v)
        remaining_set.remove(v)
        for u in neighbors[v]:
            if u in remaining_set:
                temp_degree[u] -= 1
    colors_sl, k_sl = greedy_color(reversed(sl_order))

    # 2. Welsh-Powell (WP) Ordering
    order_wp = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    colors_wp, k_wp = greedy_color(order_wp)

    # 3. DSATUR with restarts and adaptive tie-breaking
    def dsatur_run(restart=False):
        colors = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        max_color = 0
        while uncolored:
            if restart:
                # Adaptive: saturation + random noise scaled by degree
                v = -1
                max_val = -1
                for u in uncolored:
                    deg_factor = math.log(len(neighbors[u]) + 1)
                    val = sat[u] + random.random() * deg_factor * 1e-4
                    if val > max_val:
                        max_val = val
                        v = u
            else:
                # Deterministic: saturation, then degree in uncolored, then original degree
                v = -1
                max_sat = -1
                max_deg = -1
                max_orig_deg = -1
                for u in uncolored:
                    deg_in_uncolored = len(neighbors[u] & uncolored)
                    orig_deg = len(neighbors[u])
                    if sat[u] > max_sat or \
                       (sat[u] == max_sat and deg_in_uncolored > max_deg) or \
