                        max_sat = sat[u]
                        max_deg = deg_in_uncolored
                        max_orig_deg = orig_deg
                        v = u
            used = [False] * (max_color + 2)
            for u in neighbors[v]:
                if colors[u] != -1:
                    used[colors[u]] = True
            c = 0
