            best_colors_ds = colors[:]

    # 4. Independent set with dynamic saturation ordering (hybrid approach)
    colors_hybrid = [-1] * n
    uncolored_hybrid = set(range(n))
    color = 0
    while uncolored_hybrid:
        S = set()
        sat_current = [0] * n
        for v in uncolored_hybrid:
            sat_current[v] = len({colors_hybrid[u] for u in neighbors[v] if colors_hybrid[u] != -1})
        v = max(uncolored_hybrid, key=lambda x: (sat_current[x], len(neighbors[x] & uncolored_hybrid), x))
        S.add(v)
        U = uncolored_hybrid - {v} - (neighbors[v] & uncolored_hybrid)
        W = neighbors[v] & uncolored_hybrid
        while U:
            u = -1
            max_nw = -1
            min_deg_u = float('inf')
            for cand in U:
                nw = len(neighbors[cand] & W)
                deg_u = len(neighbors[cand] & U)
                if nw > max_nw or (nw == max_nw and deg_u < min_deg_u) or \
                   (nw == max_nw and deg_u == min_deg_u and cand < u):
                    max_nw = nw
                    min_deg_u = deg_u
                    u = cand
            S.add(u)
            U.remove(u)
            for w in neighbors[u]:
                if w in U:
                    U.remove(w)
                    W.add(w)
        for v in S:
            colors_hybrid[v] = color
        uncolored_hybrid -= S
        color += 1
    k_hybrid = color

    # Select best from all methods
    candidates = [
        (colors_sl, k_sl),
        (colors_wp, k_wp),
        (best_colors_ds, best_k_ds),
