                            if not visited[y] and (colors[y] == c or colors[y] == target_color):
                                visited[y] = True
                                stack.append(y)
                    count_target = 0
                    count_c = 0
                    for x in component:
                        if colors[x] == target_color:
                            count_target += 1
                        elif colors[x] == c:
                            count_c += 1
